  for (idx = 0; idx < UI_DEMO_WIFI_DRIVER_MAX_APS; idx++)
    {
      struct ui_demo_wifi_driver_scan_result result;
      struct ui_demo_wifi_ap ap;
      size_t ssid_len;
      int ret;

      memset(&result, 0, sizeof(result));
      ret = fhost_get_scan_results(NULL, idx, 1, &result);
      if (ret <= 0)
        {
