        }

      if (!result.valid_flag || result.ssid.length == 0)
        {
          continue;
        }

      memset(&ap, 0, sizeof(ap));
      ssid_len = result.ssid.length;
      if (ssid_len > UI_DEMO_WIFI_DRIVER_SSID_LEN)
        {
          ssid_len = UI_DEMO_WIFI_DRIVER_SSID_LEN;
        }

      if (ssid_len >= sizeof(ap.ssid))
