      memcpy(ap.ssid, result.ssid.array, ssid_len);
      ap.ssid[ssid_len] = '\0';
      ap.rssi = (int32_t)result.rssi;
      ap.signal = ui_demo_wifi_signal_from_rssi(ap.rssi);
      ap.channel = result.chan == NULL ? 0 :
